b="function render(){const active=document.activeElement,keepSearch=active?.classList?.contains('search'),caret=keepSearch?active.selectionStart:null,placeholder=keepSearch?active.placeholder:'';document.getElementById('pagetitle').textContent=navItems.find(n=>n[0]===page)?.[2]||'Overview';document.getElementById('pagesub').textContent=descriptions[page];document.getElementById('nav').innerHTML=navItems.map(n=>`<button class=\"${page===n[0]?'active':''}\" onclick=\"setPage('${n[0]}')\"><span class=\"ico\">${n[1]}</span>${n[2]}</button>`).join('');let view=document.getElementById('view');view.innerHTML=({home:homeView,wardrobe:wardrobeView,outfits:outfitsView,journal:journalView,grooming:groomingView,care:careView,events:eventsView,watchlist:watchView,reading:readingView,tasks:tasksView,gym:gymView,weight:weightView,education:educationView}[page])();view.classList.toggle('edit-mode',editMode);let toggle=document.getElementById('editToggle');toggle.textContent=editMode?'✎ Edit mode: on':'✎ Edit mode: off';toggle.classList.toggle('active',editMode);if(keepSearch){const next=[...view.querySelectorAll('.search')].find(x=>x.placeholder===placeholder)||view.querySelector('.search');if(next){next.focus();if(caret!==null)next.setSelectionRange(caret,caret)}}if(page==='wardrobe'||page==='outfits')hydratePhotos();if(page==='education')updatePomodoroUI();}"
