wardrobe=r'''function wardrobeView(){let cats=[...new Set(state.wardrobe.map(x=>x.Category).filter(Boolean))].sort();let arr=filtered(state.wardrobe,['Category']);let cards=arr.map(x=>`<article class="garment ${state.selectedOutfit.includes(x.id)?'selected':''} fade-in"><div class="garment-photo"><img id="photo-${x.id}" alt="Photo of ${esc(x.Name)}" hidden><span class="photo-placeholder" id="placeholder-${x.id}">${garmentEmoji(x.Category)}</span><button class="favorite ${x.favorite?'on':''}" title="Favourite" onclick="toggleFavorite('${x.id}')">${x.favorite?'♥':'♡'}</button><button class="photo-btn" onclick="document.getElementById('upload-${x.id}').click()">${x.photoKey?'Change photo':'＋ Add photo'}</button>${x.photoKey?`<button class="photo-remove" onclick="removeClothingPhoto('${x.id}')">Remove photo</button>`:''}<input id="upload-${x.id}" type="file" accept="image/*" hidden onchange="uploadClothingPhoto('${x.id}',this)"></div><div class="garment-body"><div class="garment-title">${esc(x.Name)}</div><div class="garment-meta">${esc(x.Category)} · ${esc(x['Colour / Details'])}</div><div class="garment-actions"><select onchange="updateItem('wardrobe','${x.id}','Laundry Status',this.value)">${['Clean','Worn','In Wash','To Put Away'].map(st=>`<option ${x['Laundry Status']===st?'selected':''}>${st}</option>`).join('')}</select><button class="pick-btn ${state.selectedOutfit.includes(x.id)?'on':''}" onclick="toggleOutfitItem('${x.id}')">${state.selectedOutfit.includes(x.id)?'✓ Added':'＋ Outfit'}</button><button class="smallbtn edit-mode-only" onclick="openForm('wardrobe','${x.id}')">Edit</button></div></div></article>`).join('');return `<div class="sectionintro"><p>${state.wardrobe.length} pieces. <span class="pill green">Clean</span> ready · <span class="pill">Worn</span> currently worn · <span class="pill orange">In Wash</span> dirty / washing · <span class="pill">To Put Away</span> clean, not stored.</p></div>${toolbar(cats,"openForm('wardrobe')",'Search clothes, colour, category')}<div class="gallery">${cards||'<div class="empty">No clothing matches this search.</div>'}</div>`}
'''
