# Save style intent with outfit
rep("state.outfits.unshift({id:'o'+Date.now(),name,items:[...state.selectedOutfit],note:''});", "state.outfits.unshift({id:'o'+Date.now(),name,items:[...state.selectedOutfit],note:outfitAdvice||''});", 'save outfit advice')
# Add generator functions before clearOutfit
anchor='function clearOutfit(){'
func=r'''let outfitAdvice='';
function outfitRole(item){let c=(item.Category+' '+item.Name).toLowerCase();if(/headwear|hat|beanie|cap|bucket hat/.test(c))return 'head';if(/shoe|sneaker|clog|slides|dress shoes/.test(c))return 'shoes';if(/socks/.test(c))return 'socks';if(/underwear|boxer|sleepwear|robe/.test(c))return 'base';if(/shorts|jeans|bottom|trouser|cargo|jogger|pants|jorts/.test(c))return 'bottom';if(/jacket|outerwear|blazer|hoodie|sweatshirt|knitwear|jumper|sweater/.test(c))return 'layer';if(/belt|watch|jewelry|accessor|chain|ring/.test(c))return 'accessory';if(/shirt|t-shirt|tee|polo|vest|tops/.test(c))return 'top';return 'accessory'}
function pickStyleItem(items,role,style,used){let candidates=items.filter(x=>outfitRole(x)===role&&!used.has(x.id));if(!candidates.length)return null;let rank=x=>{let text=(x.Name+' '+x.Category+' '+x['Colour / Details']).toLowerCase(),n=0;if(style==='Streetwear')n+=(/graphic|hoodie|cargo|wide-leg|sneaker|jorts/.test(text)?4:0);if(style==='Smart casual')n+=(/polo|dress|blazer|oxford|button|formal|trouser/.test(text)?5:0);if(style==='Cosy')n+=(/fleece|knit|thermal|jogger|sweater/.test(text)?5:0);if(style==='Summer')n+=(/short|linen|camp collar|slide|sandal/.test(text)?5:0);if(style==='Gym')n+=(/activewear|athletic|performance|adidas|under armour|gym/.test(text)?5:0);if(style==='Everyday')n+=(/plain|cotton|jeans|sneaker/.test(text)?2:0);if(x.favorite)n+=2;return n+Math.random()*1.8};return candidates.sort((a,b)=>rank(b)-rank(a)).slice(0,Math.min(4,candidates.length))[Math.floor(Math.random()*Math.min(4,candidates.length))]}
function colorWords(item){return ((item?.Name||'')+' '+(item?.['Colour / Details']||'')).toLowerCase()}
function generateOutfit(){let style=document.getElementById('outfitStyle')?.value||'Everyday';let ready=state.wardrobe.filter(x=>!['In Wash','Worn'].includes(x['Laundry Status']));if(!ready.length)ready=state.wardrobe.filter(x=>x['Laundry Status']!=='In Wash');let used=new Set(),look={};for(let role of ['head','top','layer','bottom','socks','shoes','accessory']){let item=pickStyleItem(ready,role,style,used);if(item){look[role]=item;used.add(item.id)}}let selected=Object.values(look);state.selectedOutfit=selected.map(x=>x.id);let top=look.top,bottom=look.bottom,layer=look.layer,shoes=look.shoes;let a=colorWords(top),b=colorWords(bottom);let palette=/black|charcoal|grey|gray/.test(a)?'The darker top gives the look a clean anchor; lighter denim or neutral shoes keep it balanced.':/white|cream|off-white|beige|tan/.test(a)?'The light top brightens the outfit; deeper trousers give it contrast.':/blue|navy/.test(a)?'The blue tones feel relaxed; grey, cream, or denim keep the palette easy.':/green|sage|olive/.test(a)?'The muted green works well with denim and warm neutral accessories.':'Keep the remaining colours calm so the main piece stands out.';let slots=['Headwear','Top','Layer','Bottoms','Socks','Shoes','Accessories'];let roleLabels={head:'headwear',top:'top',layer:'layer',bottom:'bottoms',socks:'socks',shoes:'shoes',accessory:'accessories'};let missing=[];for(let r of ['head','top','layer','bottom','socks','shoes','accessory'])if(!look[r])missing.push(roleLabels[r]);let choice=selected.map(x=>x.Category).join(', ');let vibe=style==='Smart casual'?'For a sharper finish, keep the shirt tucked and let the blazer sit open.':style==='Streetwear'?'Let the graphic or silhouette lead; keep the accessories understated.':style==='Cosy'?'Layer the knit or fleece over the base and keep the proportions relaxed.':style==='Summer'?'Keep the layers light and let the shorts or shirt carry the colour.':style==='Gym'?'This athletic combination keeps movement easy; choose performance socks with the trainers.':'This is an easy everyday mix; a small accessory adds a finishing detail.';outfitAdvice=`${palette} ${vibe}${missing.length?` Your closet doesn’t currently have a ${missing.join(', ')} item ready for this look.`:''}${top&&bottom?` Palette: ${top.Category} with ${bottom.Category}${layer?` and ${layer.Category}`:''}${shoes?`, finished with ${shoes.Category}`:''}.`:''}`;page='outfits';searchTerm='';filter='All';save();render();toast('A new head-to-toe look is ready')}
function generateFromHome(){setPage('outfits');generateOutfit()}
'''
rep(anchor,func+anchor,'outfit generator functions')
# Laundry status values for newly added items; ensure only the user's four choices remain.
