anchor='function eventsView(){'
edu=r'''function educationView(){let t=state.pomodoro;let modes=[['focus','Focus · 25'],['short','Short break · 5'],['long','Long break · 15']];let q=t.mode==='focus'?1500:t.mode==='short'?300:900;let secs=t.running?Math.max(0,Math.ceil((t.endsAt-Date.now())/1000)):t.remaining;let pct=Math.max(0,Math.min(100,(1-secs/q)*100));return `<div class="education-hero"><div><div class="eyebrow">YOUR STUDY SPACE</div><h2>One focused session at a time.</h2><p>Pick one small goal, work with the timer, then take a real break.</p></div><div class="education-spark">✦</div></div><div class="education-grid"><section class="card pomodoro-card"><div class="cardhead"><div><div class="eyebrow">POMODORO TIMER</div><h2>Focus room</h2></div><span class="pill green">${t.sessions} focus rounds</span></div><div class="timer-modes">${modes.map(([m,label])=>`<button class="timer-mode ${t.mode===m?'selected':''}" onclick="setPomodoroMode('${m}')">${label}</button>`).join('')}</div><div class="timer-ring" id="timerRing" style="--timer-pct:${pct}%"><div class="timer-center"><div class="timer-time" id="timerCount">${timerFormat(secs)}</div><div class="timer-label" id="timerModeLabel">${t.mode==='focus'?'FOCUS TIME':t.mode==='short'?'SHORT BREAK':'LONG BREAK'}</div></div></div><div class="timer-actions"><button class="btn primary" id="timerToggle" onclick="togglePomodoro()">${t.running?'Pause':'Start focus'}</button><button class="btn" onclick="resetPomodoro()">Reset</button></div><p class="timer-hint">${t.mode==='focus'?'Silence distractions. You only need to focus until the bell.':'Step away from your screen and let your mind reset.'}</p></section><section class="card blackboard-card"><div class="blackboard-mark">B</div><div class="eyebrow">COURSE HUB</div><h2>Blackboard Learn</h2><p class="muted">Open your University of Reading modules, course materials, announcements, and submissions.</p><a class="btn primary blackboard-link" href="https://www.bb.reading.ac.uk/ultra/institution-page" target="_blank" rel="noopener noreferrer">Open Blackboard <span>↗</span></a><div class="blackboard-foot">University of Reading · Learn Ultra</div></section></div><section class="card study-tips"><div class="cardhead"><h2>Your focus ritual</h2><span class="pill">A small reset</span></div><div class="focus-steps"><div><b>01</b><span>Choose one assignment or reading task.</span></div><div><b>02</b><span>Work until the focus timer ends.</span></div><div><b>03</b><span>Take a short break, then repeat.</span></div><div><b>04</b><span>After four rounds, take a longer pause.</span></div></div></section>`}
function timerFormat(n){n=Math.max(0,Math.floor(n));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function pomodoroTick(){let t=state.pomodoro;if(!t)return;if(t.running){let remaining=Math.max(0,Math.ceil((t.endsAt-Date.now())/1000));t.remaining=remaining;if(remaining===0){t.running=false;t.endsAt=0;if(t.mode==='focus'){t.sessions=(t.sessions||0)+1;t.mode=t.sessions%4===0?'long':'short'}else t.mode='focus';t.remaining=t.mode==='focus'?1500:t.mode==='short'?300:900;save();toast('Focus round complete — take a breath');if(page==='education')render()}else updatePomodoroUI()}}
function updatePomodoroUI(){let t=state.pomodoro;if(!t)return;let n=t.running?Math.max(0,Math.ceil((t.endsAt-Date.now())/1000)):t.remaining;let total=t.mode==='focus'?1500:t.mode==='short'?300:900;let count=document.getElementById('timerCount'),ring=document.getElementById('timerRing'),mode=document.getElementById('timerModeLabel'),toggle=document.getElementById('timerToggle');if(count)count.textContent=timerFormat(n);if(mode)mode.textContent=t.mode==='focus'?'FOCUS TIME':t.mode==='short'?'SHORT BREAK':'LONG BREAK';if(toggle)toggle.textContent=t.running?'Pause':'Start focus';if(ring)ring.style.setProperty('--timer-pct',`${Math.max(0,Math.min(100,(1-n/total)*100))}%`)}
function setPomodoroMode(mode){let t=state.pomodoro;t.mode=mode;t.running=false;t.endsAt=0;t.remaining=mode==='focus'?1500:mode==='short'?300:900;save();render()}
function togglePomodoro(){let t=state.pomodoro;if(t.running){t.remaining=Math.max(0,Math.ceil((t.endsAt-Date.now())/1000));t.running=false;t.endsAt=0}else{t.endsAt=Date.now()+t.remaining*1000;t.running=true}save();updatePomodoroUI()}
function resetPomodoro(){let t=state.pomodoro;t.running=false;t.endsAt=0;t.remaining=t.mode==='focus'?1500:t.mode==='short'?300:900;save();updatePomodoroUI()}
'''
