home=r'''function homeView(){let laundry=state.wardrobe.filter(x=>x['Laundry Status']==='In Wash').length;let low=state.grooming.filter(x=>/low|out|empty/i.test(x['Stock Level'])).length;let next=state.events.filter(x=>x.date).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);let open=state.tasks.filter(x=>!x.done).length;let date=new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'});let ready=state.wardrobe.filter(x=>['Clean','To Put Away'].includes(x['Laundry Status']));return `<section class="home-hero"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="hero-content"><div class="eyebrow">${date.toUpperCase()} · YOUR PERSONAL SPACE</div><h2>Make today feel a little more <em>you.</em></h2><p>Your routines, plans, and little wins in one place.</p><div class="hero-actions"><button class="btn primary" onclick="generateFromHome()">✦ Style me an outfit</button><button class="btn hero-glass" onclick="setPage('education');togglePomodoro()">◷ Start a focus sprint</button><button class="btn hero-glass" onclick="openJournalForm()">✎ Write a thought</button></div></div><div class="hero-orb-main"><span>✧</span></div></section><div class="grid stats">${countNote('Clothing pieces',state.wardrobe.length,'in your visual closet')}${countNote('Grooming items',state.grooming.length,low?`${low} running low or out`:'your care shelf')}${countNote('Ready to wear',ready.length,'clean or ready to put away')}${countNote('Open tasks',open,'things still on your list')}</div><div class="grid two"><section class="card"><div class="cardhead"><h2>On your radar</h2><button class="smallbtn" onclick="setPage('events')">Calendar ↗</button></div>${next.length?`<div class="list">${next.map(e=>`<div class="listrow"><div><b>${esc(e.name)}</b><div class="muted">${fmtDate(e.date)} ${e.time?`· ${esc(e.time)}`:''}</div></div><span class="pill">${esc(e.kind||'Event')}</span></div>`).join('')}</div>`:`<div class="empty">Nothing on the calendar yet.</div>`}<button class="btn quick-cta" onclick="openForm('events')">＋ Add something to the calendar</button></section><section class="card"><div class="cardhead"><h2>Quick capture</h2><span class="pill green">Tap to add</span></div><div class="quick"><button onclick="openForm('tasks')"><b>＋ Task</b><span>Capture a to do</span></button><button onclick="openForm('events')"><b>＋ Event</b><span>Plan a date</span></button><button onclick="openForm('watchlist')"><b>＋ Show</b><span>Save a series</span></button><button onclick="openForm('reading')"><b>＋ Book</b><span>Add a read</span></button><button onclick="openForm('gym')"><b>＋ Workout</b><span>Log training</span></button><button onclick="openForm('weight')"><b>＋ Weigh in</b><span>Log weight</span></button><button onclick="openJournalForm()"><b>＋ Journal</b><span>Capture today</span></button><button onclick="setPage('education')"><b>＋ Study</b><span>Open focus room</span></button></div></section></div><div class="grid two" style="margin-top:16px"><section class="card"><div class="cardhead"><h2>Outfit of the moment</h2><button class="smallbtn" onclick="generateFromHome()">Surprise me ✦</button></div><div class="list">${ready.slice(0,3).map(x=>`<div class="listrow"><div><b>${esc(x.Name)}</b><div class="muted">${esc(x.Category)} · ${esc(x['Colour / Details'])}</div></div><span class="pill green">${esc(x['Laundry Status'])}</span></div>`).join('')||'<div class="muted">Mark a few pieces clean to get outfit ideas.</div>'}</div></section><section class="card"><div class="cardhead"><h2>Today’s focus</h2><button class="smallbtn" onclick="setPage('tasks')">Tasks ↗</button></div>${state.tasks.filter(x=>!x.done).slice(0,4).map(t=>`<label class="checkline"><input type="checkbox" onchange="toggleTask('${t.id}')"><span>${esc(t.name)}</span></label>`).join('')||'<div class="empty">No open tasks. Enjoy the breathing room.</div>'}</section></div><div class="home-footer"><span class="home-footer-star">✦</span><span>Small steps count. Your dashboard saves automatically in this browser.</span><button class="smallbtn" onclick="setPage('education')">Study space →</button></div>`}
'''
